head.script:
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
// 세션정보를 얻기위한 함수사용

scwin.clickIsuCd;
scwin.clickIsuKorAbbrv;
scwin.procJob;
scwin.fr_SecuGrpId = SECUGRP_ID_EW;
scwin.fr_MktId = $c.lc.fn_getMktId();

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_Top);
        await scwin.setIsurcode();
        await scwin.setLiqucode();
        if (scwin.fr_MktId !== '9') {
            img_TASK_DD.hide();
            img_STRT_DD.hide();
            img_LIST_DD.hide();
        }
        edt_TASK_DD.setValue($c.ut.cGetToday("yyyymmdd"));
        edt_END_DD.setValue(edt_TASK_DD.getValue());
        await scwin.setDate();
        await scwin.listSync1();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF45001.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description btn_Search 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        if (await scwin.checkForm()) {
            if (img_Elwlist.getSelectedTabIndex() === 1) {
                await scwin.listSync1();
            } else if (img_Elwlist.getSelectedTabIndex() === 2) {
                await scwin.listSync2();
            } else {
                await $c.win.alert('오류가 발생하였습니다. 담당자에게 연락 하시기 바랍니다.');
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF45001.btn_Search_onclick" });
    }
};

