 * @name img_Excel1_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Excel1_onclick = async function() {
    try {
        $c.stf.doLogSave("ULDSTF45001.xml", SCREN_PROCS_TP_CD_07);
        if (dts_List_1.getRowCount() > 0) {
            $c.data.downloadGridViewExcel(grd_List_1, {fileName: $c.lc.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + "거래부진으로 인한 상장폐지 우려 종목", type: "8"});
        } else {
            await $c.win.alert(NO_EXCEL_DATA);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF45001.img_Excel1_onclick" });
    }
};

