/**
 * @method
 * @name listSync1
 * @description list Sync1 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync1 = async function() {
    url += "&{P}PROC_DD=" + edt_TASK_DD.getValue();
    url += "&{P}STRT_DD=" + edt_STRT_DD.getValue();
    url += "&{P}LIST_DD=" + edt_LIST_DD.getValue();
    url += "&{P}ISUR_CD=" + cmd_Isur_Cd.BindColVal;
    url += "&{P}LP_MBR_NO=" + cmd_liqu_lpNm.BindColVal;
    const sbmOptions = {
        id : "sbm_dts_List_1",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List_1=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

