/**
 * @method
 * @name setDate
 * @description set Date 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setDate = async function() {
    url += "&{P}DATE1=" + scwin.getStrtDate();
    url += "&{P}DATE2=" + scwin.getListDate();
    const sbmOptions = {
        id : "sbm_dts_date",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_date=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    for (let i = 1; i <= dts_date.getRowCount(); i++) {
        if (dts_date.getCellData(i, 'CD_ID') === '1') {
            edt_STRT_DD.setValue(dts_date.getCellData(i, 'VALUE'));
        } else if (dts_date.getCellData(i, 'CD_ID') === '2') {
            edt_LIST_DD.setValue(dts_date.getCellData(i, 'VALUE'));
        }
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getStrtDate
 * @description get Strt Date 처리
 * @returns {void}
 * @hidden N
 */
scwin.getStrtDate = function() {
    let yyyymmdd = edt_TASK_DD.getValue();
    let yyyy = yyyymmdd.substring(0, 4);
    let mm = yyyymmdd.substring(4, 6);
    let dd = yyyymmdd.substring(6, 8);
    if (mm === 01) {
        mm = 12;
        yyyy = yyyy - 1;
    } else {
        mm = mm - 1;
    }
    return '' + yyyy + $c.ut.cGetZero(mm, 2) + dd;
};

/**
 * @method
 * @name getListDate
 * @description get List Date 처리
 * @returns {void}
 * @hidden N
 */
scwin.getListDate = function() {
    let yyyymmdd = edt_TASK_DD.getValue();
    let yyyy = yyyymmdd.substring(0, 4);
    let mm = yyyymmdd.substring(4, 6);
    let dd = yyyymmdd.substring(6, 8);
    if (mm === 02) {
        mm = 12;
        yyyy = yyyy - 1;
    } else if (mm === 01) {
        mm = 11;
        yyyy = yyyy - 1;
    } else {
        mm = mm - 2;
    }
    return '' + yyyy + $c.ut.cGetZero(mm, 2) + dd;
};

/**
 * @method
 * @name setContnId
 * @description set Contn Id 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setContnId = function(obj) {
    scwin.clickIsuCd = dts_List_1.getCellData(Number(obj), "ISU_CD");
    scwin.clickIsuKorAbbrv = dts_List_1.getCellData(Number(obj), "ISU_KOR_ABBRV");
};

/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    if (edt_TASK_DD.text.length !== 8) {
        await $c.win.alert("[마감일]을 정확히 입력하세요.");
        return false;
    }
    if (edt_STRT_DD.text.length !== 8) {
        await $c.win.alert("[1개월 거래량 산정기간 시작일]을 정확히 입력하세요.");
        return false;
    }
    if (edt_LIST_DD.text.length !== 8) {
        await $c.win.alert("[상장제한일]을 정확히 입력하세요.");
        return false;
    }
    return true;
};
